from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    # Sort tiles by area descending to potentially prune faster
    sorted_tiles = sorted(tiles, key=lambda x: x[0] * x[1], reverse=True)
    tile_areas = [a * b for a, b in sorted_tiles]
    grid = [[False for _ in range(w)] for _ in range(h)]

    def solve(covered_count, available_mask):
        if covered_count == h * w:
            return True

        # Pruning: check if remaining tiles have enough area
        remaining_area = 0
        for i in range(n):
            if (available_mask >> i) & 1:
                remaining_area += tile_areas[i]
        if remaining_area < (h * w - covered_count):
            return False

        # Find the first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:
            return True

        for i in range(n):
            if (available_mask >> i) & 1:
                a, b = sorted_tiles[i]
                # Try both orientations
                for th, tw in set([(a, b), (b, a)]):
                    if r + th <= h and c + tw <= w:
                        # Check if the tile fits
                        can_place = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[r + dr][c + dc]:
                                    can_place = False
                                    break
                            if not can_place:
                                break

                        if can_place:
                            # Place the tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = True

                            if solve(covered_count + th * tw, available_mask ^ (1 << i)):
                                return True

                            # Backtrack
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = False
        return False

    return solve(0, (1 << n) - 1)

